export type TokenKind = "sol" | "hl" | "rh" | "x" | "btc" | "eth" | "uni";

const N = 1024;

type Box = [number, number, number, number]; // x0, x1, y0, y1 as fractions of the face

/** Bounding box of anything drawn on a canvas, from its alpha. */
function inkBox(c: OffscreenCanvas): Box {
  const g = c.getContext("2d")!;
  const { data, width, height } = g.getImageData(0, 0, c.width, c.height);
  let x0 = width, x1 = -1, y0 = height, y1 = -1;
  for (let y = 0; y < height; y++)
    for (let x = 0; x < width; x++)
      if (data[(y * width + x) * 4 + 3] > 127) {
        if (x < x0) x0 = x;
        if (x > x1) x1 = x;
        if (y < y0) y0 = y;
        if (y > y1) y1 = y;
      }
  return [x0, x1 + 1, y0, y1 + 1];
}

/** Draw `draw` (in 24-unit icon space) into the face so its ink fills `box`. */
function fit(g: OffscreenCanvasRenderingContext2D, box: Box, draw: (h: OffscreenCanvasRenderingContext2D) => void, keepAspect = true, rotDeg = 0) {
  const S = 1024;
  const tmp = new OffscreenCanvas(S, S);
  const h = tmp.getContext("2d")!;
  h.scale(S / 24, S / 24);
  if (rotDeg) {
    h.translate(12, 12);
    h.scale(0.8, 0.8);
    h.rotate((rotDeg * Math.PI) / 180);
    h.translate(-12, -12);
  }
  draw(h);
  const [ix0, ix1, iy0, iy1] = inkBox(tmp);
  let [bx0, bx1, by0, by1] = box.map((v) => v * N) as Box;
  if (keepAspect) {
    // keep the mark's own aspect: fit the height, centre on the measured box
    const aspect = (ix1 - ix0) / (iy1 - iy0);
    const hgt = by1 - by0;
    const cx = (bx0 + bx1) / 2;
    bx0 = cx - (hgt * aspect) / 2;
    bx1 = cx + (hgt * aspect) / 2;
  }
  g.drawImage(tmp, ix0, iy0, ix1 - ix0, iy1 - iy0, bx0, by0, bx1 - bx0, by1 - by0);
}

const FACE: Record<TokenKind, string> = {
  sol: "#070513",
  hl: "#092a21",
  rh: "#1fd66c",
  x: "#101115",
  btc: "#f5941f",
  eth: "#060412",
  uni: "#f9a4dd",
};

export function faceCanvas(kind: TokenKind): OffscreenCanvas {
  const c = new OffscreenCanvas(N, N);
  const g = c.getContext("2d")!;
  g.fillStyle = FACE[kind];
  g.fillRect(0, 0, N, N);
  switch (kind) {
    case "hl":
      fit(g, [0.152, 0.875, 0.273, 0.777], (h) => {
        h.fillStyle = "#6affde";
        h.fill(new Path2D(SVG.hyperliquid));
      }, false);
      break;
    case "x":
      fit(g, [0.137, 0.951, 0.348, 0.641], (h) => {
        h.fillStyle = "#fefcfe";
        h.fill(new Path2D(SVG.spacex));
      }, false);
      break;
    case "rh":
      fit(g, [0.326, 0.574, 0.213, 0.846], (h) => {
        h.fillStyle = "#fefefb";
        h.fill(new Path2D(SVG.robinhood));
      }, true, -36);
      break;
    case "sol":
      fit(g, [0.215, 0.772, 0.262, 0.703], (h) => {
        h.fillStyle = "#80ffe9";
        h.fill(new Path2D(SVG.solTop));
        h.fillStyle = "#8ae0e6";
        h.fill(new Path2D(SVG.solMid));
        h.fillStyle = "#b5aef0";
        h.fill(new Path2D(SVG.solBot));
      }, false);
      break;
    case "btc":
      fit(g, [0.23, 0.801, 0.158, 0.846], (h) => {
        // the Simple Icons mark is a disc with the ₿ knocked out: keep only the ₿
        h.save();
        h.beginPath();
        h.arc(12, 12, 11.2, 0, Math.PI * 2);
        h.clip();
        h.fillStyle = "#ffffff";
        h.fillRect(0, 0, 24, 24);
        h.globalCompositeOperation = "destination-out";
        h.fill(new Path2D(SVG.bitcoin), "evenodd");
        h.restore();
      });
      break;
    case "eth": {
      const draw = (h: OffscreenCanvasRenderingContext2D) => {
        const tri = (col: string, pts: number[]) => {
          h.fillStyle = col;
          h.beginPath();
          h.moveTo(pts[0], pts[1]);
          for (let i = 2; i < pts.length; i += 2) h.lineTo(pts[i], pts[i + 1]);
          h.closePath();
          h.fill();
        };
        // the classic octahedron, from the Web3 Icons geometry, shaded as sampled
        tri("#a0a8ce", [12, 3, 6.375, 12.166, 12, 9.651]);
        tri("#7276a3", [12, 3, 17.625, 12.166, 12, 9.651]);
        tri("#7577a3", [6.375, 12.166, 12, 9.651, 12, 15.43]);
        tri("#544e8d", [17.625, 12.166, 12, 9.651, 12, 15.43]);
        tri("#a0a6d1", [6.375, 13.215, 12, 16.477, 12, 21]);
        tri("#767bb1", [17.625, 13.215, 12, 16.477, 12, 21]);
      };
      fit(g, [0.36, 0.76, 0.164, 0.803], draw);
      break;
    }
    case "uni":
      // Uniswap's unicorn, drawn by the mono Web3 Icons path
      fit(g, [0.217, 0.789, 0.15, 0.826], (h) => {
        h.fillStyle = "#e600c1";
        for (const [d, rule] of UNI_PATHS) h.fill(new Path2D(d), rule);
      });
      break;
  }
  return c;
}

export interface TokenCoin extends THREE.Group {
  userData: { mats: THREE.Material[] };
}

const wallGeo = (() => {
  const g = new THREE.CylinderGeometry(1, 1, 0.3, 128, 1, true);
  g.rotateX(Math.PI / 2);
  return g;
})();
const discGeo = new THREE.CircleGeometry(1, 128);

export function tokenCoin(kind: TokenKind, wall = "#eaedfe", name = `coin-${kind}`): TokenCoin {
  const grp = new THREE.Group() as TokenCoin;
  grp.name = name;
  const tex = new THREE.CanvasTexture(faceCanvas(kind) as unknown as HTMLCanvasElement);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 8;
  const faceMat = new THREE.MeshBasicMaterial({ map: tex });
  const plain = new THREE.MeshBasicMaterial({ color: FACE[kind] });
  const wallMat = new THREE.MeshBasicMaterial({ color: wall });
  const front = new THREE.Mesh(discGeo, faceMat);
  front.position.z = 0.15;
  front.name = `${name}-face`;
  const back = new THREE.Mesh(discGeo, plain);
  back.rotation.y = Math.PI;
  back.position.z = -0.15;
  const side = new THREE.Mesh(wallGeo, wallMat);
  side.name = `${name}-wall`;
  grp.add(side, back, front);
  grp.userData.mats = [faceMat, plain, wallMat];
  return grp;
}

